// 参考解：前驱指针法，一遍扫描删除所有 x
#include <iostream>
using namespace std;

struct LNode {
    int data;
    LNode *next;
};

typedef LNode *LinkList;

int main() {
    int n;
    if (!(cin >> n)) return 0;

    LinkList L = new LNode;
    L->next = nullptr;
    LNode *r = L;
    for (int i = 0; i < n; i++) {
        int v; cin >> v;
        LNode *s = new LNode;
        s->data = v; s->next = nullptr;
        r->next = s; r = s;
    }

    int target;
    cin >> target;

    LNode *pre = L, *p = L->next;
    while (p != nullptr) {
        if (p->data == target) {
            pre->next = p->next;   // 越过 p
            delete p;              // 释放
            p = pre->next;         // 从新的后继继续
        } else {
            pre = p;
            p = p->next;
        }
    }

    if (L->next == nullptr) {
        cout << "empty\n";
    } else {
        for (LNode *q = L->next; q != nullptr; q = q->next) {
            cout << q->data << (q->next == nullptr ? '\n' : ' ');
        }
    }
    return 0;
}
